114	function Get-ModuleUrl($store, $cfg, $moduleKey) {
115	  $plat = ''
116	  if ($store.platformName) { $plat = [string]$store.platformName }
117	  elseif ($store.platform) { $plat = [string]$store.platform }
118	  $mapKey = switch ($moduleKey) {
119	    'shop_daily' { 'shopDailyUrl' }
120	    'health_daily' { 'healthUrl' }
121	    'finance_daily' { 'financeUrl' }
122	    default { $null }
123	  }
124	  $defaults = @{
125	    # compass/data-overview 常停在 Key metrics 占位；首页卡片稳定有 GMV/订单/客户
126	    shop_daily    = 'https://seller-uk.tiktok.com/homepage'
127	    health_daily  = 'https://seller-uk.tiktok.com/health-center'
128	    finance_daily = 'https://seller-uk.tiktok.com/finance/bills'
129	  }
130	  if ($mapKey -and $cfg.$mapKey) {
131	    $block = $cfg.$mapKey
132	    if ($block.byPlatform -and $plat) {
133	      foreach ($p in $block.byPlatform.PSObject.Properties) {
134	        if ($plat -eq [string]$p.Name -or $plat -like ("*{0}*" -f $p.Name)) { return [string]$p.Value }
135	      }
136	    }
137	    if ($block.default) { return [string]$block.default }
138	  }
139	  if ($cfg.urls -and $cfg.urls.$moduleKey) { return [string]$cfg.urls.$moduleKey }
140	  return [string]$defaults[$moduleKey]
141	}
