/* TikTok ads dashboard scraper for ziniao-cli page exec. No // comments (minified to one line). */
(function () {
  function cleanText(t) {
    return String(t ?? '')
      .replace(/\s+/g, ' ')
      .trim();
  }

  function detectCurrency(text) {
    const s = String(text ?? '');
    if (/[£]|GBP|英镑/i.test(s)) return 'GBP';
    if (/[€]|EUR|欧元/i.test(s)) return 'EUR';
    if (/[¥￥]|CNY|RMB|元/i.test(s) && !/\$/.test(s)) return 'CNY';
    if (/\$|USD|美金|美元/i.test(s)) return 'USD';
    return null;
  }

  function parseNumber(value) {
    if (value == null || value === '') return null;
    if (typeof value === 'number' && Number.isFinite(value)) return value;
    let s = String(value).trim();
    if (!s || s === '-' || s === '—') return null;
    s = s
      .replace(/[,\s]/g, '')
      .replace(/[¥$€£￥]/g, '')
      .replace(/USD|GBP|EUR|CNY|RMB|美金|美元|英镑|欧元/gi, '')
      .replace(/%/g, '');
    const paren = s.match(/^\((.+)\)$/);
    if (paren) s = `-${paren[1]}`;
    const n = Number(s);
    return Number.isFinite(n) ? n : null;
  }

  /** 当前预算单元格常见：「10.00 USD 日预算：10.00 USD」→ 取日预算优先 */
  function parseBudgetNumber(value) {
    if (value == null || value === '') return null;
    if (typeof value === 'number' && Number.isFinite(value)) return value;
    const raw = String(value).trim();
    if (!raw || raw === '-' || raw === '—') return null;
    const m =
      raw.match(/日预算\s*[:：]?\s*([0-9]+(?:[.,][0-9]+)?)/i) ||
      raw.match(/([0-9]+(?:[.,][0-9]+)?)\s*(?:USD|GBP|EUR|CNY|美金|美元)?/i);
    if (m) return parseNumber(m[1]);
    return parseNumber(raw);
  }

  const HEADER_ALIASES = {
    planStatus: ['开/关', '开关', '投放开关', 'enable', 'enabled', 'switch', 'on/off', 'toggle'],
    // P1: 比 spend/roi 更具体的列优先匹配
    targetRoi: ['目标 roi', '目标roi', '目标 roas', '目标roas', 'target roi', 'target roas'],
    avgOrderCost: [
      '平均下单成本',
      '平均下单',
      'cost per order',
      'cost per purchase',
      'avg order cost',
      'cpa'
    ],
    netCost: ['净成本', 'net cost', 'net spend'],
    // 勿用裸「预算」：会误吃「创意作品加热预算」列，把日预算盖成 null
    dailyBudget: ['当前预算', '日预算', 'daily budget', 'current budget'],
    deliveryStatus: ['状态', '投放状态', '计划状态', 'status', 'delivery status'],
    campaign: [
      '品名',
      '广告计划名称',
      '广告系列',
      '广告系列名称',
      '系列名称',
      'campaign',
      'campaign name',
      'product',
      '名称'
    ],
    spend: ['广告花费', '广告成本', '花费', '成本', '消耗', 'cost', 'spend', 'ad spend'],
    orders: [
      '销量',
      '订单',
      'sku 订单',
      'sku订单',
      'sku 订单数',
